export type BackupKind = "auto" | "manual" | "pre_migration" | "pre_restore" | 
/**
 *  The database a PC had before it became a till (M5): kept, listed, never logged in
 *  `backups_log` (the copy is taken before the database opens).
 */
"pre_pairing";

/**
 *  Who a backup belongs to, read from the copy itself (never from this PC's files): the demo
 *  shop's mark, and its place on a shop network.
 */
export type BackupOrigin = {
	/**  The demo shop's database (`demo::META_DEMO`). */
	demo: boolean,
	/**  Its role on the shop's network (`lan_local`); `standalone` before M5. */
	lanRole: TerminalRole,
	/**  A till's main PC, by its shop name. */
	hostName: string | null,
	/**  The copy's own terminal code (a till's `C2`). */
	terminalCode: string | null,
	/**  A main PC's paired tills not revoked. */
	activeTills: number,
};

export type BackupPreview = {
	status: PreviewStatus,
	schemaVersion: number,
	appSchemaVersion: number,
	companyName: string | null,
	/**  The last validated ticket: what the shop will find at the top of its history. */
	lastTicket: LastDocument | null,
	documents: number,
	products: number,
	customers: number,
	/**  The newest journal row: the last thing anybody did in that copy. */
	lastActivityAt: number | null,
	/**  Active owners of that copy: who may restore it. */
	owners: OwnerTile[],
	/**  Whose copy it is (the demo shop's, a till's, a main PC's); `None` when it cannot be read. */
	origin: BackupOrigin | null,
};

/**  What the app knows about its backups, for the banner every signed-in user sees. */
export type BackupStatus = {
	/**
	 *  The last automatic backup attempt of this run; `None` before it ran or when today's
	 *  backup already existed.
	 */
	lastAuto: AutoBackupOutcome | null,
	/**  When the newest backup in the backups folder was made. */
	newestAt: number | null,
	/**  The newest backup is more than [`STALE_AFTER_DAYS`] business days old. */
	stale: boolean,
	/**
	 *  A backup copy failed its integrity check and so did the live database, or the integrity
	 *  check of the live database failed or could not run: stop selling and restore.
	 */
	databaseDamaged: boolean,
	/**
	 *  The code of this run's last failed second copy (`mirror_unavailable`…); `None` after a
	 *  good one.
	 */
	mirrorError: string | null,
};

