/**
 *  A cart edit worth a line in the journal, as the till asks for it: the cart on screen (it
 *  lives in the webview), never a figure. The backend values it itself, so a journal row cannot
 *  carry a name or an amount kept from an older preview (AUD-001, RPT-018).
 */
export type CartEventInput = 
/**  Line `index` (from 0) leaves the cart before payment (`sales.void_line`). */
{ kind: "line_voided"; cart: Cart; index: number } | 
/**  The whole cart is abandoned (`sales.void_line`). */
{ kind: "cart_cancelled"; cart: Cart } | 
/**
 *  Line `index` (from 0) goes down to `qty` (milli-units), a partial void
 *  (`sales.void_line`): the cart is sent as it stands, before the change.
 */
{ kind: "qty_reduced"; cart: Cart; index: number; qty: Qty };

/**  One line as the cashier built it. */
export type CartLine = {
	/**  `None` for an open item typed at the till (SAL-018). */
	productId: string | null,
	/**  The open item's name; ignored for catalogue products. */
	description: string | null,
	qty: Qty,
	/**  A price override (catalogue product) or the open item's price. */
	unitPrice: Money | null,
	discount: Discount,
	/**  The open item's tax rate; ignored for catalogue products. */
	taxRateId: string | null,
	note: string | null,
	/**
	 *  The unit price shown when the line was added: a held cart recalled later reports the
	 *  lines whose price changed since (spec §7.4).
	 */
	expectedUnitPrice: Money | null,
	/**
	 *  A weighed package (a scale label, the scale panel): a line of its own that the till never
	 *  merges another scan into, kept when the ticket is held (VRT-010). Pricing ignores it;
	 *  carts held before it read as `false`.
	 */
	separate?: boolean,
};

