export type ChainAnchor = {
	lastSeq: number,
	lastHash: string,
	/**  The rows since the previous Z verified. */
	intact: boolean,
};

/**
 *  What [`verify_chain`] found. `last_seq` and `last_hash` name the last row that verified;
 *  recorded outside the database (Z-report, backup, cloud), they anchor the journal.
 */
export type ChainReport = {
	/**  Rows present in the journal. */
	rows: number,
	/**
	 *  `None` when the chain is intact. `Some(n)` means the chain breaks at or before `n`: the
	 *  edited row for a plain edit; the next row for a deleted row or for an edit whose own
	 *  hash was recomputed; `last_seq + 1` when rows were deleted at the end (the
	 *  `sqlite_sequence` high-water mark is above the last row).
	 */
	firstBrokenSeq: number | null,
	/**  `seq` of the last row that verified, 0 when none did. */
	lastSeq: number,
	/**  `hash` of that row, [`GENESIS_HASH`] when none did. */
	lastHash: string,
};

/**  Every chain checked on the day of the export (`chains.json`, the manifest, the summary). */
export type ChainSummary = {
	documents: DocChainReport[],
	audit: ChainReport,
	closures: TerminalClosures[],
	/**  The versement receipts `RV…` (outside `documents`, anchored in the journal). */
	receipts: ReceiptChainReport,
	/**  The journals of the tills this main PC keeps (M5), revoked ones included: evidence. */
	tillJournals: TillJournalChain[],
	/**
	 *  The first `merge_seq` of the main PC's chain over every till's journal that does not
	 *  recompute (`sync::journal::verify_merge`), `None` when it is intact or empty.
	 */
	tillMergeFirstBroken: number | null,
};

