/**
 *  What closing a round will book, shown before it is (VRT-100): the collections by method in the
 *  order of the route, the cash the driver hands in — each cash collection with the droit de
 *  timbre its customer pays on it, as the versement of [`close`] computes it — and the stops not
 *  delivered.
 */
export type ClosePreview = {
	collected: ([PaymentMethod, Money])[],
	cashToHandIn: Money,
	failed: number,
};

/**
 *  Z close result: the report, and the backup taken after it (CSH-011); a failed backup does
 *  not undo the close, it is reported with its error code.
 */
export type Closed = Closed_Serialize | Closed_Deserialize;

/**  A closed round and the versements its collections became, in stop order. */
export type ClosedRound = {
	round: Round,
	versements: Collected[],
};

export type ClosedRoundDone = {
	round: ClosedRound,
	/**  Every versement receipt went to the print queue. */
	printQueued: boolean,
};

/**
 *  Z close result: the report, and the backup taken after it (CSH-011); a failed backup does
 *  not undo the close, it is reported with its error code.
 */
export type Closed_Deserialize = {
	z: ZReport_Deserialize,
	backup: BackupInfo | null,
	backupError: string | null,
};

/**
 *  Z close result: the report, and the backup taken after it (CSH-011); a failed backup does
 *  not undo the close, it is reported with its error code.
 */
export type Closed_Serialize = {
	z: ZReport_Serialize,
	backup: BackupInfo | null,
	backupError: string | null,
};

/**  The closure chain of a terminal (AUD-004). */
export type ClosureChainReport = {
	/**  Closures present for the terminal. */
	rows: number,
	/**
	 *  `None` when the chain is intact. Otherwise the first Z that fails (its report does not
	 *  hash to its hash or link to the previous Z, a column disagrees with the report, its Z
	 *  number does not follow the previous one, or its grand total is not the previous one plus
	 *  the day's net), or else the first Z issued whose closure is gone (the terminal's Z
	 *  counter is past the last closure, or a closed session has none).
	 */
	firstBrokenZ: string | null,
	/**  `hash` of the last closure that verified, [`GENESIS_HASH`] when none did. */
	lastHash: string,
};

